#version 300 es

//This is the default shader for the shader editor!
//These functions are here and are written for the GLSL 3.0 specification.
//You can revert it to GLSL 1.0 by removing the version number

precision highp float;
// defualt precision for floats

//our output for color
out highp vec4 fragColor;
//Base Variables
attribute highp vec4 a_position;
attribute highp vec4 a_color;
attribute highp vec2 a_texCoord;

varying highp vec4 v_color;
varying highp vec2 v_texCoord;

varying highp float v_depth;
uniform highp float u_timer;
uniform highp mat4 u_transform;
//rectangle board
uniform highp float u_wide;
uniform highp float u_height;

uniform highp float u_offsetX;
uniform highp float u_offsetY;
uniform highp float Reso_X_m;
uniform highp float Reso_Y_m;
uniform highp float Box_angle;

//circle board
uniform highp float u_offsetXC;
uniform highp float u_offsetYC;
uniform highp float u_Size_c;
//Pen+ Textures
uniform mediump vec2 u_res;
uniform highp vec4 u_color;
//Base functions

//Some missing math functions
highp float log10(highp float a) {
  return log(a)/log(10.0);
}

highp float eulernum(highp float a) {
  return 2.718 * a;
}

//Psuedorandomness
highp vec4 pcg4d(highp vec4 v)
{
  v = v * 1664525.0 + 1013904223.0;

  v.x += v.y*v.w;
  v.y += v.z*v.x;
  v.z += v.x*v.y;
  v.w += v.y*v.z;

  v.x += v.z*v.w;
  v.y += v.y*v.x;
  v.z += v.x*v.w;
  v.w += v.y*v.x;

  return vec4(v);
}

highp vec4 daveRandomRange(highp float lowR, highp float highR)
{
  lowp float r = (gl_FragCoord.x * 50.25313532) + (gl_FragCoord.y * 21.5453) + u_timer;
  highp float randomizer = r*r/u_timer/5398932.234523;
  return clamp(vec4(
  fract(sin(mod(randomizer*(91.3458), 1440.0)) * 47453.5453),
  fract(sin(mod(randomizer*(80.3458), 1440.0)) * 48456.5453),
  fract(sin(mod(randomizer*(95.3458), 1440.0)) * 42457.5453),
  fract(sin(mod(randomizer*(85.3458), 1440.0)) * 47553.5453)
  ), lowR, highR);
}

highp vec4 HSVToRGB(highp float hue, highp float saturation, highp float value, highp float a) {
  highp float huePrime = mod(hue,360.0);
  highp float c = (value/100.0) * (saturation/100.0);
  highp float x = c * (1.0 - abs(mod(huePrime/60.0, 2.0) - 1.0));
  highp float m = (value/100.0) - c;
  highp float r = 0.0;
  highp float g = 0.0;
  highp float b = 0.0;

  if (huePrime >= 0.0 && huePrime < 60.0) {
      r = c;
      g = x;
      b = 0.0;
  } else if (huePrime >= 60.0 && huePrime < 120.0) {
      r = x;
      g = c;
      b = 0.0;
  } else if (huePrime >= 120.0 && huePrime < 180.0) {
      r = 0.0;
      g = c;
      b = x;
  } else if (huePrime >= 180.0 && huePrime < 240.0) {
      r = 0.0;
      g = x;
      b = c;
  } else if (huePrime >= 240.0 && huePrime < 300.0) {
      r = x;
      g = 0.0;
      b = c;
  } else if (huePrime >= 300.0 && huePrime < 360.0) {
      r = c;
      g = 0.0;
      b = x;
  }
  r += m;
  g += m;
  b += m;
  return vec4(r, g, b, a);
}

highp vec4 HSVToRGB(highp vec4 colorInput) {
  return HSVToRGB(colorInput.x, colorInput.y, colorInput.z, colorInput.w);
}

highp vec4 RGBToHSV(highp float r, highp float g, highp float b, highp float a) {
  //Get the brightest and darkest channels
  highp float CMax = r;
  if (g > CMax) { CMax = g; }
  if (b > CMax) { CMax = b; }

  highp float CMin = r;
  if (g < CMin) { CMin = g; }
  if (b < CMin) { CMin = b; }

  highp float Delta = CMax - CMin;

  highp float H = 0.0;

  //Multiply and get the Hue
  if (CMax == r) {
      H = 60.0 * mod(((g - b) / Delta), 6.0);
  }
  if (CMax == g) {
      H = 60.0 * ((b - r) / Delta + 2.0);
  }
  if (CMax == b) {
      H = 60.0 * ((r - g) / Delta + 4.0);
  }

  //Set the saturation
  highp float S = 0.0;
  if (CMax != 0.0) {
      S = Delta / CMax;
  }

  return vec4(H, S * 100.0, CMax * 100.0, a);
}

highp vec4 RGBToHSV(highp vec4 colorInput) {
  return RGBToHSV(colorInput.x, colorInput.y, colorInput.z, colorInput.w);
}

highp vec4 rotation(highp vec4 invec4) {
  return vec4(
    (invec4.y) * u_transform[1][0] + (invec4.x) * u_transform[1][1],
    (invec4.y) * u_transform[1][1] - (invec4.x) * u_transform[1][0],
    invec4.zw
  );
}
uniform sampler2D u_skin;



vec2 rotate(vec2 uv, vec2 res) {

    uv = (uv / res) * 2.0 - 1.0;


    uv.x *= (res.x * Reso_X_m) / (res.y * Reso_Y_m);




    uv.x /= res.x / res.y;

    uv = (uv + 1.0) * 0.5;
    return uv;
}


//Fragment Shader
void fragment() {
    vec2 uv = gl_FragCoord.xy;


    vec2 ruv = rotate(uv, u_res);

    vec2 boardcheck = vec2( ((sin((Box_angle  + 270.0)*0.0174533)) * (u_offsetX - ruv.x)) + ((cos((Box_angle  + 270.0)*0.0174533))) * (u_offsetY - ruv.y) ,
                            ((sin((Box_angle  + 180.0)*0.0174533)) * (u_offsetX - ruv.x)) + ((cos((Box_angle  + 180.0)*0.0174533))) * (u_offsetY - ruv.y));
    fragColor = vec4(texture(u_skin,v_texCoord).x * (u_color.x / 100.0),texture(u_skin,v_texCoord).y * (u_color.y / 100.0),texture(u_skin,v_texCoord).z * (u_color.z / 100.0),texture(u_skin,v_texCoord).w * (u_color.w / 100.0));

      float distance = float(sqrt(float(((ruv.x - u_offsetXC) * (ruv.x - u_offsetXC)) + ((ruv.y - u_offsetYC) * (ruv.y - u_offsetYC)))));
    if ((boardcheck.x <= float((-u_wide)) || boardcheck.x >= float(u_wide) || boardcheck.y <= float((-u_height)) ||  boardcheck.y >= float(u_height))){

    discard;
    }
 if ((distance >= u_Size_c)) {
     discard;
    }

}//Vertex Shader
void vertex() {
  gl_Position = (rotation(a_position) + vec4(u_transform[0][2],u_transform[0][3],0,0)) * vec4(a_position.w * u_transform[0][0],a_position.w * -u_transform[0][1],1,1) - vec4(0,0,1,0);
  v_color = a_color;
  v_texCoord = a_texCoord;

}

