  if (b > CMax) { CMax = b; }

  highp float CMin = r;
  if (g < CMin) { CMin = g; }
  if (b < CMin) { CMin = b; }

  highp float Delta = CMax - CMin;

  highp float H = 0.0;

  //Multiply and get the Hue
  if (CMax == r) {
