vec3 mod289(vec3 x) {
	return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec4 mod289(vec4 x) {
	return x - floor(x * (1.0 / 289.0)) * 289.0;
}

vec4 permute(vec4 x) {
	return mod289(((x*34.0)+10.0)*x);
}

vec4 taylorInvSqrt(vec4 r) {
	return 1.79284291400159 - 0.85373472095314 * r;
}

float snoise(vec3 v) {
	const vec2  C = vec2(1.0/6.0, 1.0/3.0) ;
	const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);

	// First corner
	vec3 i  = floor(v + dot(v, C.yyy) );
	vec3 x0 =   v - i + dot(i, C.xxx) ;

	// Other corners
	vec3 g = step(x0.yzx, x0.xyz);
	vec3 l = 1.0 - g;
	vec3 i1 = min( g.xyz, l.zxy );
	vec3 i2 = max( g.xyz, l.zxy );

	//   x0 = x0 - 0.0 + 0.0 * C.xxx;
	//   x1 = x0 - i1  + 1.0 * C.xxx;
	//   x2 = x0 - i2  + 2.0 * C.xxx;
	//   x3 = x0 - 1.0 + 3.0 * C.xxx;
	vec3 x1 = x0 - i1 + C.xxx;
	vec3 x2 = x0 - i2 + C.yyy; // 2.0*C.x = 1/3 = C.y
	vec3 x3 = x0 - D.yyy;      // -1.0+3.0*C.x = -0.5 = -D.y

	// Permutations
	i = mod289(i);
	vec4 p = permute( permute( permute(
				i.z + vec4(0.0, i1.z, i2.z, 1.0 ))
			+ i.y + vec4(0.0, i1.y, i2.y, 1.0 ))
			+ i.x + vec4(0.0, i1.x, i2.x, 1.0 ));

	// Gradients: 7x7 points over a square, mapped onto an octahedron.
	// The ring size 17*17 = 289 is close to a multiple of 49 (49*6 = 294)
	float n_ = 0.142857142857; // 1.0/7.0
	vec3  ns = n_ * D.wyz - D.xzx;

	vec4 j = p - 49.0 * floor(p * ns.z * ns.z);  //  mod(p,7*7)

	vec4 x_ = floor(j * ns.z);
	vec4 y_ = floor(j - 7.0 * x_ );    // mod(j,N)

	vec4 x = x_ *ns.x + ns.yyyy;
	vec4 y = y_ *ns.x + ns.yyyy;
	vec4 h = 1.0 - abs(x) - abs(y);

	vec4 b0 = vec4( x.xy, y.xy );
	vec4 b1 = vec4( x.zw, y.zw );

	//vec4 s0 = vec4(lessThan(b0,0.0))*2.0 - 1.0;
	//vec4 s1 = vec4(lessThan(b1,0.0))*2.0 - 1.0;
	vec4 s0 = floor(b0)*2.0 + 1.0;
	vec4 s1 = floor(b1)*2.0 + 1.0;
	vec4 sh = -step(h, vec4(0.0));

	vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
	vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;

	vec3 p0 = vec3(a0.xy,h.x);
	vec3 p1 = vec3(a0.zw,h.y);
	vec3 p2 = vec3(a1.xy,h.z);
	vec3 p3 = vec3(a1.zw,h.w);

	//Normalise gradients
	vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
	p0 *= norm.x;
	p1 *= norm.y;
	p2 *= norm.z;
	p3 *= norm.w;

	// Mix final noise value
	vec4 m = max(0.5 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
	m = m * m;
	return 105.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1),
									dot(p2,x2), dot(p3,x3) ) );
}

uniform float u_Scale;
uniform float u_Intensity;

// 화면 전체 연못 물결 효과 제어 변수
uniform float u_RippleStrength; // 0.0 = 끔, 기본 권장값 0.01~0.05
uniform float u_RippleSpeed;    // 물결 속도, 기본 권장값 1.0

float rand(vec2 a) {
	return fract(sin(dot(mod(a, vec2(1000.0)).xy, vec2(12.9898, 78.233))) * 43758.5453);
}

float ease(float t) {
	return t * t * (3.0 - 2.0 * t);
}

float rainDist(vec2 p, float scale, float intensity) {
	// scale everything
	p *= 0.1;
	// sheer
	p.x += p.y * 0.1;
	// scroll
	p.y -= u_timer * 500.0 / scale;
	// expand Y
	p.y *= 0.03;
	float ix = floor(p.x);
	// shift Y
	p.y += mod(ix, 2.0) * 0.5 + (rand(vec2(ix)) - 0.5) * 0.3;
	float iy = floor(p.y);
	vec2 index = vec2(ix, iy);
	// mod
	p -= index;
	// shift X
	p.x += (rand(index.yx) * 2.0 - 1.0) * 0.35;
	// distance
	vec2 a = abs(p - 0.5);
	float res = max(a.x * 0.8, a.y * 0.5) - 0.1;
	// decimate
	bool empty = rand(index) < mix(1.0, 0.1, intensity);
	return empty ? 1.0 : res;
}

float rippleHeight(vec2 p, vec2 pos, float age, float size, float modSize, float thickness) {
	float strength = 1.0 - exp(-(1.0 - age) * 1.0);
	float h = max(0.0, 1.0 - abs(length(mod(p - pos + modSize * 0.5, vec2(modSize)) - modSize * 0.5) - size * age) / thickness);
	h = h * h * (3.0 - 2.0 * h); // smoothstep
	return h * strength;
}

void fragment() {
	vec2 wpos = v_texCoord;
	vec2 origWpos = wpos;
	float intensity = u_Intensity;

	vec3 add = vec3(0);
	float rainSum = 0.0;

	const int numLayers = 4;
	float scales[4];
	scales[0] = 1.0;
	scales[1] = 1.8;
	scales[2] = 2.6;
	scales[3] = 4.8;

	for (int i = 0; i < numLayers; i++) {
		float scale = scales[i];
		float r = rainDist(vec2(1,-1) * v_texCoord * scale / u_Scale + 500.0 * float(i), scale, intensity);
		if (r < 0.0) {
			float v = (1.0 - exp(r * 5.0)) / scale * 2.0;
			wpos.x += v * 4.0 * u_Scale;
			wpos.y -= v * 0.8 * u_Scale;
			add += vec3(0.1, 0.15, 0.2) * v;
			rainSum += (1.0 - rainSum) * 0.75;
		}
	}

	// 화면 전체에 적용되는 연못 수면형 물결 왜곡
	// 원본 좌표(origWpos)를 기준으로 하므로 빗방울 왜곡과 독립적으로 작동합니다.
	float rippleTime = u_timer * u_RippleSpeed;
	vec2 rippleCoord = origWpos * 6.2831853;

	vec2 rippleOffset;
	rippleOffset.x = sin(rippleCoord.y * 2.1 + rippleTime * 1.7)
	               * cos(rippleCoord.x * 1.3 - rippleTime * 0.8);
	rippleOffset.y = cos(rippleCoord.x * 1.8 - rippleTime * 1.2)
	               * sin(rippleCoord.y * 1.1 + rippleTime * 0.9);

	// 강도를 변수로 조절하며, 화면 전체에 동일하게 적용합니다.
	wpos += rippleOffset * u_RippleStrength;

	// 기본 샘플: 빗방울 및 연못 물결에 의해 왜곡된 좌표
	vec3 baseColor = texture2D(u_skin, wpos).xyz;

	// rainSum은 실제로 굴절이 발생한 영역의 마스크 역할을 합니다.
	// 여러 레이어가 겹쳐도 0~1 범위로 제한합니다.
	float distortionMask = clamp(rainSum, 0.0, 1.0);

	// 빗방울의 굴곡이 생긴 부분에만 적용하는 국소 블러입니다.
	// 화면 전체가 흐려지지 않도록 distortionMask로 블러 강도를 제한합니다.
	vec2 blurStep = 1.0 / max(u_res, vec2(1.0));
	vec3 blurColor = baseColor;
	blurColor += texture2D(u_skin, wpos + vec2( blurStep.x, 0.0)).xyz;
	blurColor += texture2D(u_skin, wpos + vec2(-blurStep.x, 0.0)).xyz;
	blurColor += texture2D(u_skin, wpos + vec2(0.0,  blurStep.y)).xyz;
	blurColor += texture2D(u_skin, wpos + vec2(0.0, -blurStep.y)).xyz;
	blurColor *= 0.2;

	// 굴곡이 강한 곳일수록 블러가 조금 더 강해집니다.
	float blurStrength = smoothstep(0.02, 0.35, distortionMask) * 0.65;
	vec3 color = mix(baseColor, blurColor, blurStrength);

	// 굴절이 발생한 부분에만 미세한 색상 변화를 추가합니다.
	color += vec3(0.1, 0.15, 0.2) * distortionMask * 0.08;

	gl_FragColor = vec4(color, 1.0);
}

